=== FILE: deep_counter_props.sv ===
// Formal properties for deep_counter (interface_spec.md, sections 1-4).
// Checker deep_counter_props binds one DUT instance by instantiation; the top
// deep_counter_fv checks the boundary and default parameter values.
`default_nettype none

module deep_counter_props #(
    parameter integer LIMIT = 99
) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire clr
);
    localparam [6:0] F_LAST = LIMIT;

    wire [6:0] count;
    wire       carry;

    deep_counter #(
        .LIMIT(LIMIT)
    ) dut (
        .clk  (clk),
        .rst_n(rst_n),
        .en   (en),
        .clr  (clr),
        .count(count),
        .carry(carry)
    );

    // f_past_valid is 0 only in the first cycle.
    reg f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    // Only constraint: the run starts with reset asserted.
    always @(*)
        if (!f_past_valid)
            assume(!rst_n);

    // [req:DC-CARRY] combinational, every cycle.
    always @(*)
        assert(carry == (en && !clr && (count == F_LAST)));

    // [req:DC-RANGE] count never above LIMIT after reset (induction invariant).
    always @(*)
        if (f_past_valid)
            assert(count <= F_LAST);

    always @(posedge clk) begin
        if (f_past_valid) begin
            // [req:DC-RESET]
            if (!$past(rst_n))
                assert(count == 7'd0);
            // [req:DC-CLEAR] clear wins over enable
            if ($past(rst_n) && $past(clr))
                assert(count == 7'd0);
            // [req:DC-COUNT] increment below LIMIT, wrap to 0 at LIMIT
            if ($past(rst_n) && !$past(clr) && $past(en))
                assert(count == (($past(count) == F_LAST) ? 7'd0 : ($past(count) + 7'd1)));
            // [req:DC-HOLD]
            if ($past(rst_n) && !$past(clr) && !$past(en))
                assert(count == $past(count));
        end
    end

    // Non-vacuity covers: each assertion antecedent is exercised.
    always @(posedge clk) begin
        if (f_past_valid) begin
            // reset of a non-zero count, after the initial reset
            cover($past(f_past_valid) && !$past(rst_n) && ($past(count) != 7'd0));
            // clear of a non-zero count while enable is high
            cover($past(rst_n) && $past(clr) && $past(en) && ($past(count) != 7'd0));
            // increment below LIMIT
            cover($past(rst_n) && !$past(clr) && $past(en) && ($past(count) != F_LAST));
            // wrap from LIMIT to 0
            cover($past(rst_n) && !$past(clr) && $past(en) && ($past(count) == F_LAST) && (count == 7'd0));
            // hold of a non-zero count
            cover($past(rst_n) && !$past(clr) && !$past(en) && ($past(count) != 7'd0));
            // count reaches LIMIT
            cover(count == F_LAST);
            // carry out asserted
            cover(carry);
        end
    end

    // Top bit of count exercised where LIMIT can reach it.
    generate
        if (LIMIT >= 64) begin : g_top_bit
            always @(posedge clk)
                if (f_past_valid)
                    cover(count[6]);
        end
    endgenerate
endmodule

module deep_counter_fv (
    input wire clk,
    input wire rst_n_min,
    input wire en_min,
    input wire clr_min,
    input wire rst_n_def,
    input wire en_def,
    input wire clr_def,
    input wire rst_n_max,
    input wire en_max,
    input wire clr_max
);
    deep_counter_props #(.LIMIT(1)) u_min (
        .clk(clk), .rst_n(rst_n_min), .en(en_min), .clr(clr_min)
    );

    deep_counter_props #(.LIMIT(99)) u_def (
        .clk(clk), .rst_n(rst_n_def), .en(en_def), .clr(clr_def)
    );

    deep_counter_props #(.LIMIT(127)) u_max (
        .clk(clk), .rst_n(rst_n_max), .en(en_max), .clr(clr_max)
    );
endmodule

`default_nettype wire
